with mapped as (select p.evidence_run_id,p.identity_key as old_key,concat_ws('|',p.business_line,c.normalized_name,coalesce(c.brand_id::text,''),coalesce(c.category_id::text,'')) as new_key from lihen_private.product_identity_evidence_proposals p cross join lateral (select c.normalized_name,c.brand_id,c.category_id from lihen_private.product_import_candidates c where c.run_id=(select r.candidate_run_id from lihen_private.product_review_evidence_runs r where r.id=p.evidence_run_id) and c.source_reference_id=(p.evidence->'member_reference_ids'->>0) limit 1) c) update lihen_private.product_identity_evidence_proposals p set identity_key=m.new_key from mapped m where p.evidence_run_id=m.evidence_run_id and p.identity_key=m.old_key;
